const DISTRICTS = [
D('eiffel', 'Eiffeltoren & West-Parijs', '#EE7B30', 'De toren, musea en brede lanen',
 [[48.8700, 2.2750], [48.8700, 2.2900], [48.8640, 2.3000], [48.8608, 2.3080], [48.8440, 2.3080], [48.8440, 2.2750]],
 ['Het westen van Parijs is ruim en statig: brede lanen, ministeries en het Champ de Mars dat van de Eiffeltoren naar de École Militaire loopt.', 'Aan de overkant van de Seine liggen de paleizen van de Trocadéro en een rij musea, van wereldkunst tot hedendaagse kunst.', 'Tussen de monumenten ligt een echte buurt rond de marktstraat Rue Cler, waar Parijzenaars gewoon boodschappen doen.'],
 ['Uitzicht vanaf de Trocadéro', 'De Eiffeltoren bij nacht', 'Musée du quai Branly', 'Picknicken op het Champ de Mars'],
 [{ title: 'Toren, rivier en Trocadéro', desc: 'Een rondje om de toren met de beste uitzichten.', stops: ['rue-cler', 'champ-de-mars', 'eiffel', 'quai-branly', 'bir-hakeim', 'trocadero', 'palais-tokyo'] }],
 { name: 'Eiffel Tower & Western Paris', tag: 'The tower, museums and broad avenues', text: ['Western Paris is spacious and stately: broad avenues, ministries and the Champ de Mars running from the Eiffel Tower to the École Militaire.', 'Across the Seine lie the Trocadéro palaces and a row of museums, from world art to contemporary art.', 'Between the monuments is a real neighbourhood around the market street Rue Cler, where Parisians do their shopping.'], highlights: ['The view from the Trocadéro', 'The Eiffel Tower at night', 'Musée du quai Branly', 'A picnic on the Champ de Mars'], routes: [{ title: 'Tower, river and Trocadéro', desc: 'A loop around the tower with the best views.' }] }),
D('champs', 'Champs-Élysées & Grands Boulevards', '#E8B01A', 'Grote lanen, paleizen en warenhuizen',
 [[48.8790, 2.2850], [48.8790, 2.3400], [48.8690, 2.3420], [48.8665, 2.3218], [48.8618, 2.3218], [48.8605, 2.3100], [48.8640, 2.3000], [48.8700, 2.2900]],
 ['De Champs-Élysées werd aangelegd als verlengde as van het Louvre en groeide uit tot de paradelaan van Frankrijk. Langs het onderste deel liggen de paleizen van de wereldtentoonstelling van 1900.', 'Naar het oosten liet baron Haussmann in de 19e eeuw brede boulevards door de oude stad slaan, met het operahuis van Garnier als middelpunt.', 'Het is het Parijs van warenhuizen, theaters en grote gebaren.'],
 ['De Arc de Triomphe', 'De grote trap van de Opéra Garnier', 'Het dak van de Galeries Lafayette', 'De gouden Pont Alexandre III'],
 [{ title: 'Van de Arc naar de Opéra', desc: 'De grote as af en langs de boulevards.', stops: ['arc-triomphe', 'champs', 'grand-palais', 'petit-palais', 'alexandre', 'concorde', 'madeleine', 'garnier', 'lafayette'] }],
 { name: 'Champs-Élysées & Grands Boulevards', tag: 'Grand avenues, palaces and department stores', text: ['The Champs-Élysées was laid out as an extension of the Louvre\'s axis and grew into France\'s parade avenue. Along its lower part stand the palaces of the 1900 World\'s Fair.', 'To the east, Baron Haussmann cut broad boulevards through the old city in the 19th century, with Garnier\'s opera house at their heart.', 'This is the Paris of department stores, theatres and grand gestures.'], highlights: ['The Arc de Triomphe', 'The grand staircase of the Opéra Garnier', 'The roof of the Galeries Lafayette', 'The golden Pont Alexandre III'], routes: [{ title: 'From the Arc to the Opéra', desc: 'Down the great axis and along the boulevards.' }] }),
D('louvre', 'Louvre & Les Halles', '#8B6CF0', 'Paleis, tuin en passages',
 [[48.8665, 2.3218], [48.8690, 2.3420], [48.8690, 2.3510], [48.8566, 2.3510], [48.8585, 2.3405], [48.8605, 2.3330], [48.8618, 2.3218]],
 ['Eeuwenlang woonden de Franse koningen in het Louvre. Toen het hof naar Versailles verhuisde werd het paleis een museum en de tuin een openbare wandelplaats.', 'Ten oosten ervan lag eeuwenlang de centrale markt, Les Halles, de "buik van Parijs". Nu is het een winkelcentrum, maar de straten eromheen zijn nog vol eten.', 'Tussen beide liggen de overdekte passages uit de 19e eeuw, de voorlopers van het warenhuis.'],
 ['De Mona Lisa en de piramide', 'Monets Waterlelies', 'De tuin van het Palais-Royal', 'De Bourse de Commerce', 'Galerie Vivienne'],
 [{ title: 'De historische as', desc: 'Van de Orangerie door de Tuileries en het Louvre naar het Palais-Royal.', stops: ['orangerie', 'tuileries', 'louvre', 'palais-royal', 'vivienne'] },
  { title: 'Passages en markten', desc: 'Overdekte passages, een graanbeurs en de lekkerste straat.', stops: ['palais-royal', 'vivienne', 'bourse-commerce', 'saint-eustache', 'montorgueil'] }],
 { name: 'Louvre & Les Halles', tag: 'Palace, garden and passages', text: ['For centuries the French kings lived in the Louvre. When the court moved to Versailles the palace became a museum and the garden a public promenade.', 'To the east lay the central market for centuries, Les Halles, the "belly of Paris". Now it is a shopping centre, but the streets around it are still full of food.', 'In between are the 19th-century covered passages, forerunners of the department store.'], highlights: ['The Mona Lisa and the pyramid', 'Monet\'s Water Lilies', 'The Palais-Royal garden', 'The Bourse de Commerce', 'Galerie Vivienne'], routes: [{ title: 'The historic axis', desc: 'From the Orangerie through the Tuileries and the Louvre to the Palais-Royal.' }, { title: 'Passages and markets', desc: 'Covered passages, a grain exchange and the tastiest street.' }] }),
D('montmartre', 'Montmartre & Pigalle', '#E0487F', 'De heuvel, kunstenaars en cabaret',
 [[48.8790, 2.3200], [48.8930, 2.3200], [48.8930, 2.3520], [48.8790, 2.3520]],
 ['Montmartre was lang een dorp buiten de stad, met wijngaarden en molens. Eind 19e eeuw trokken kunstenaars naar de goedkope ateliers: Renoir, Toulouse-Lautrec, Van Gogh en later Picasso.', 'Aan de voet van de heuvel ligt Pigalle, de wijk van het cabaret en de Moulin Rouge.', 'Op de heuvel voelt het nog altijd als een dorp, met trappen, steile straatjes en het mooiste uitzicht van de stad.'],
 ['Uitzicht vanaf de Sacré-Cœur', 'De straatjes rond de Place du Tertre', 'De tuin van het Musée de Montmartre', 'Een show in de Moulin Rouge'],
 [{ title: 'De heuvel op', desc: 'Van de Rue des Martyrs via de ateliers naar de basiliek.', stops: ['martyrs', 'je-t-aime', 'bateau-lavoir', 'tertre', 'musee-montmartre', 'sacre-coeur'] },
  { title: 'Pigalle en de begraafplaats', desc: 'Cabaret, kunstenaarsgraven en dorpse straten.', stops: ['moulin-rouge', 'cimetiere-montmartre', 'bateau-lavoir', 'tertre'] }],
 { name: 'Montmartre & Pigalle', tag: 'The hill, artists and cabaret', text: ['Montmartre was long a village outside the city, with vineyards and windmills. In the late 19th century artists moved into its cheap studios: Renoir, Toulouse-Lautrec, Van Gogh and later Picasso.', 'At the foot of the hill lies Pigalle, the district of cabaret and the Moulin Rouge.', 'On the hill it still feels like a village, with stairs, steep lanes and the finest view in the city.'], highlights: ['The view from the Sacré-Cœur', 'The lanes around Place du Tertre', 'The Musée de Montmartre garden', 'A show at the Moulin Rouge'], routes: [{ title: 'Up the hill', desc: 'From Rue des Martyrs past the studios to the basilica.' }, { title: 'Pigalle and the cemetery', desc: 'Cabaret, artists\' graves and village streets.' }] }),
D('marais', 'Le Marais', '#3E7BF0', 'Herenhuizen, musea en de joodse wijk',
 [[48.8665, 2.3510], [48.8665, 2.3680], [48.8545, 2.3690], [48.8540, 2.3600], [48.8558, 2.3532], [48.8566, 2.3510]],
 ['Het Marais was ooit moerasland. In de 17e eeuw bouwde de adel hier herenhuizen rond de Place des Vosges; later raakte de wijk in verval en werd hij een buurt van werkplaatsen.', 'Rond de Rue des Rosiers ligt de oude joodse wijk, met bakkers en falafel. Tegenwoordig is het ook het hart van het homo-uitgaansleven.', 'De herenhuizen zijn nu musea: Picasso, de geschiedenis van Parijs, Victor Hugo.'],
 ['De Place des Vosges', 'Musée Picasso', 'Falafel in de Rue des Rosiers', 'Lunchen in de Marché des Enfants Rouges'],
 [{ title: 'Herenhuizen en falafel', desc: 'Van het stadhuis door de joodse wijk naar de Place des Vosges.', stops: ['hotel-de-ville', 'shoah', 'as-fallafel', 'carnavalet', 'picasso', 'enfants-rouges', 'vosges', 'victor-hugo'] }],
 { name: 'Le Marais', tag: 'Mansions, museums and the Jewish quarter', text: ['The Marais was once marshland. In the 17th century the nobility built mansions around the Place des Vosges; later the area declined into a district of workshops.', 'Around Rue des Rosiers lies the old Jewish quarter, with bakeries and falafel. Today it is also the heart of gay nightlife.', 'The mansions are now museums: Picasso, the history of Paris, Victor Hugo.'], highlights: ['The Place des Vosges', 'Musée Picasso', 'Falafel on Rue des Rosiers', 'Lunch at the Marché des Enfants Rouges'], routes: [{ title: 'Mansions and falafel', desc: 'From the city hall through the Jewish quarter to the Place des Vosges.' }] }),
D('iles', 'De eilanden', '#2F7FA0', 'Notre-Dame en de Sainte-Chapelle',
 [[48.8585, 2.3405], [48.8560, 2.3530], [48.8540, 2.3600], [48.8520, 2.3620], [48.8500, 2.3600], [48.8505, 2.3540], [48.8521, 2.3500], [48.8529, 2.3460], [48.8545, 2.3420], [48.8560, 2.3405]],
 ['Op het Île de la Cité begon Parijs, als nederzetting op een eiland in de Seine. Hier staan de kathedraal, de koninklijke kapel en het oude paleis.', 'Na de brand van 2019 is Notre-Dame zorgvuldig gerestaureerd en weer open.', 'Het buureiland Île Saint-Louis is stil en deftig, met 17e-eeuwse huizen en het beroemdste ijs van de stad.'],
 ['Notre-Dame', 'Het glas van de Sainte-Chapelle', 'De punt van het eiland bij de Pont Neuf', 'IJs op het Île Saint-Louis'],
 [{ title: 'Het oudste Parijs', desc: 'Van de Pont Neuf over beide eilanden.', stops: ['pont-neuf', 'sainte-chapelle', 'conciergerie', 'notre-dame', 'berthillon'] }],
 { name: 'The islands', tag: 'Notre-Dame and the Sainte-Chapelle', text: ['Paris began on the Île de la Cité, as a settlement on an island in the Seine. The cathedral, the royal chapel and the old palace stand here.', 'After the 2019 fire Notre-Dame was carefully restored and is open again.', 'The neighbouring Île Saint-Louis is quiet and genteel, with 17th-century houses and the city\'s most famous ice cream.'], highlights: ['Notre-Dame', 'The glass of the Sainte-Chapelle', 'The tip of the island at Pont Neuf', 'Ice cream on the Île Saint-Louis'], routes: [{ title: 'The oldest Paris', desc: 'From Pont Neuf across both islands.' }] }),
D('latin', 'Quartier Latin', '#1FA37A', 'Universiteit, Romeinen en markten',
 [[48.8545, 2.3420], [48.8529, 2.3460], [48.8521, 2.3500], [48.8505, 2.3540], [48.8500, 2.3600], [48.8465, 2.3670], [48.8380, 2.3640], [48.8380, 2.3450], [48.8435, 2.3400], [48.8500, 2.3420]],
 ['De Quartier Latin dankt zijn naam aan de studenten van de Sorbonne, die tot de Revolutie Latijn spraken. Het is al acht eeuwen de wijk van de universiteit.', 'Onder de straten liggen Romeinse resten: baden onder het Musée de Cluny en een amfitheater tussen de huizen.', 'Het is een wijk van boekwinkels, kleine bioscopen, markten en goedkope eethuizen.'],
 ['Shakespeare and Company', 'De dame met de eenhoorn in Cluny', 'Het Panthéon', 'De markt in de Rue Mouffetard', 'Muntthee in de Grande Mosquée'],
 [{ title: 'Van de Seine naar de Mouffetard', desc: 'Boeken, middeleeuwen en een Romeins amfitheater.', stops: ['shakespeare', 'cluny', 'sorbonne', 'pantheon', 'mouffetard', 'arenes', 'mosquee', 'jardin-plantes', 'ima'] }],
 { name: 'Latin Quarter', tag: 'University, Romans and markets', text: ['The Latin Quarter owes its name to the students of the Sorbonne, who spoke Latin until the Revolution. It has been the university district for eight centuries.', 'Roman remains lie beneath its streets: baths under the Musée de Cluny and an amphitheatre among the houses.', 'It is a neighbourhood of bookshops, small cinemas, markets and cheap places to eat.'], highlights: ['Shakespeare and Company', 'The Lady and the Unicorn at Cluny', 'The Panthéon', 'The market on Rue Mouffetard', 'Mint tea at the Grand Mosque'], routes: [{ title: 'From the Seine to the Mouffetard', desc: 'Books, the Middle Ages and a Roman amphitheatre.' }] }),
D('saint-germain', 'Saint-Germain & Invalides', '#C0508A', 'Cafés, musea en de Luxembourgtuin',
 [[48.8615, 2.3080], [48.8620, 2.3330], [48.8560, 2.3405], [48.8545, 2.3420], [48.8500, 2.3420], [48.8435, 2.3400], [48.8435, 2.3300], [48.8455, 2.3150], [48.8440, 2.3080]],
 ['Rond de oudste kerk van Parijs groeide een wijk van uitgevers, galeries en cafés. Na de oorlog zaten Sartre, De Beauvoir en Camus hier de hele dag op het terras.', 'Naar het westen wordt het statiger, met ministeries, het Musée Rodin en de gouden koepel van de Invalides.', 'De Luxembourgtuin is de achtertuin van de wijk.'],
 ['Impressionisten in het Musée d\'Orsay', 'Het terras van Café de Flore', 'De Luxembourgtuin', 'Het graf van Napoleon'],
 [{ title: 'Van Orsay naar de Luxembourg', desc: 'Kunst, cafés en de mooiste tuin van Parijs.', stops: ['orsay', 'saint-germain', 'flore', 'procope', 'saint-sulpice', 'luxembourg'] },
  { title: 'Invalides en Rodin', desc: 'Napoleon, beelden en een warenhuis.', stops: ['invalides', 'rodin', 'bon-marche'] }],
 { name: 'Saint-Germain & Invalides', tag: 'Cafés, museums and the Luxembourg Gardens', text: ['Around the oldest church in Paris grew a district of publishers, galleries and cafés. After the war Sartre, de Beauvoir and Camus sat on the terraces all day.', 'To the west it grows grander, with ministries, the Musée Rodin and the golden dome of the Invalides.', 'The Luxembourg Gardens are the neighbourhood\'s back garden.'], highlights: ['Impressionists at the Musée d\'Orsay', 'The terrace of Café de Flore', 'The Luxembourg Gardens', 'Napoleon\'s tomb'], routes: [{ title: 'From Orsay to the Luxembourg', desc: 'Art, cafés and the loveliest garden in Paris.' }, { title: 'Invalides and Rodin', desc: 'Napoleon, sculpture and a department store.' }] }),
D('bastille', 'Bastille & Oost-Parijs', '#D4A017', 'Revolutie, markten en het kanaal',
 [[48.8760, 2.3560], [48.8760, 2.4000], [48.8450, 2.4000], [48.8450, 2.3700], [48.8545, 2.3690], [48.8665, 2.3680], [48.8665, 2.3560]],
 ['Bij de Bastille begon in 1789 de Revolutie. Het oosten van Parijs was eeuwenlang de wijk van meubelmakers en arbeiders.', 'Nu is het jong en levendig: markten, bars in de Rue Oberkampf en het Canal Saint-Martin waar Parijzenaars op zomeravonden aan het water zitten.', 'Verder naar het oosten ligt Père-Lachaise, de beroemdste begraafplaats ter wereld.'],
 ['Het Canal Saint-Martin', 'Père-Lachaise', 'De Coulée verte op het oude viaduct', 'De Marché d\'Aligre'],
 [{ title: 'Viaduct en markt', desc: 'Van de Bastille over het groene viaduct naar de markt.', stops: ['bastille', 'opera-bastille', 'coulee-verte', 'aligre'] },
  { title: 'Kanaal en Oberkampf', desc: 'Langs het kanaal naar de bars en de begraafplaats.', stops: ['canal-st-martin', 'charbon', 'pere-lachaise'] }],
 { name: 'Bastille & Eastern Paris', tag: 'Revolution, markets and the canal', text: ['The Revolution began at the Bastille in 1789. For centuries eastern Paris was the district of furniture makers and workers.', 'Today it is young and lively: markets, bars on Rue Oberkampf and the Canal Saint-Martin, where Parisians sit by the water on summer evenings.', 'Further east lies Père Lachaise, the most famous cemetery in the world.'], highlights: ['The Canal Saint-Martin', 'Père Lachaise', 'The Coulée verte on the old viaduct', 'The Marché d\'Aligre'], routes: [{ title: 'Viaduct and market', desc: 'From the Bastille along the green viaduct to the market.' }, { title: 'Canal and Oberkampf', desc: 'Along the canal to the bars and the cemetery.' }] }),
D('montparnasse', 'Montparnasse', '#6FA73A', 'Brasseries, begraafplaats en catacomben',
 [[48.8455, 2.3150], [48.8435, 2.3300], [48.8380, 2.3450], [48.8280, 2.3450], [48.8280, 2.3080], [48.8440, 2.3080]],
 ['In de jaren twintig verhuisde het kunstenaarsleven van Montmartre naar Montparnasse. Hemingway, Picasso en Modigliani zaten in de grote brasseries op de boulevard.', 'Onder de wijk lopen de catacomben, oude steengroeven vol beenderen.', 'Boven alles uit steekt de Tour Montparnasse, met het beste uitzicht over Parijs.'],
 ['De catacomben', 'Uitzicht vanaf de Tour Montparnasse', 'Dineren in La Coupole', 'De begraafplaats van Montparnasse'],
 [{ title: 'Onder en boven Montparnasse', desc: 'Van de toren naar de catacomben.', stops: ['tour-montparnasse', 'coupole', 'cimetiere-montparnasse', 'cartier', 'catacombes'] }],
 { name: 'Montparnasse', tag: 'Brasseries, cemetery and catacombs', text: ['In the 1920s artistic life moved from Montmartre to Montparnasse. Hemingway, Picasso and Modigliani sat in the great brasseries on the boulevard.', 'Beneath the district run the catacombs, old quarries full of bones.', 'Above it all rises the Tour Montparnasse, with the best view over Paris.'], highlights: ['The catacombs', 'The view from the Tour Montparnasse', 'Dinner at La Coupole', 'Montparnasse Cemetery'], routes: [{ title: 'Below and above Montparnasse', desc: 'From the tower to the catacombs.' }] }),
];

